import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 쪽 크기 기본 20, 최대 200
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_FORMAT = /^\d{4}-\d{2}-\d{2}$/;
const DIGITS = /^\d+$/;

// 가정: 지원하는 현황 유형 (나머지 유형은 입력에 원천 테이블이 없어 TODO)
const TYPE_PLAN_VS_ACTUAL = '자금계획 대비 실적';
const TYPE_PROFIT = '자금손익현황';
const TYPE_DAILY = '일일자금 및 분개현황';

// 가정: 실적 금액 = 조회 기간 내 '승인' 전표의 차변 합계. 입금은 수입 결의서, 출금은 지출 결의서 전표로 본다.
const PLAN_VS_ACTUAL_SQL = `
  SELECT p.cash_direction AS "cashDirection",
         CAST(SUM(p.plan_amount) AS numeric) AS "planAmount",
         CAST(COALESCE((
           SELECT SUM(v.debit_total)
           FROM journal_voucher v
           JOIN expense_resolution r ON r.expense_resolution_id = v.expense_resolution_id
           WHERE v.status = '승인'
             AND v.voucher_date BETWEEN CAST(:fromDate AS date) AND CAST(:toDate AS date)
             AND r.resolution_type = CASE p.cash_direction WHEN '입금' THEN '수입' ELSE '지출' END
         ), 0) AS numeric) AS "actualAmount"
  FROM fund_plan p
  WHERE p.plan_start_date <= CAST(:toDate AS date)
    AND p.plan_end_date >= CAST(:fromDate AS date)
    AND (CAST(:fundSubjectId AS bigint) IS NULL OR p.fund_subject_id = CAST(:fundSubjectId AS bigint))
  GROUP BY p.cash_direction`;

// 가정: 자금손익현황은 자금 손익 양식 구성 과목별 계획 금액을 보이고, 과목별 실적은 원천이 없어 0으로 둔다.
const PROFIT_SQL = `
  SELECT f.form_name AS "formName",
         f.fund_subject_id AS "fundSubjectId",
         s.subject_name AS "subjectName",
         f.sort_order AS "sortOrder",
         CAST(COALESCE(SUM(p.plan_amount), 0) AS numeric) AS "planAmount",
         CAST(0 AS numeric) AS "actualAmount"
  FROM fund_profit_form_item f
  JOIN fund_subject s ON s.fund_subject_id = f.fund_subject_id
  LEFT JOIN fund_plan p ON p.fund_subject_id = f.fund_subject_id
    AND p.plan_start_date <= CAST(:toDate AS date)
    AND p.plan_end_date >= CAST(:fromDate AS date)
  WHERE (CAST(:fundSubjectId AS bigint) IS NULL OR f.fund_subject_id = CAST(:fundSubjectId AS bigint))
  GROUP BY f.fund_profit_form_item_id, f.form_name, f.fund_subject_id, s.subject_name, f.sort_order`;

// 일일자금 및 분개현황: 자금일보 일자의 전표 정보를 참조한다.
const DAILY_SQL = `
  SELECT d.report_date AS "reportDate",
         d.approval_status AS "approvalStatus",
         COUNT(v.journal_voucher_id) AS "voucherCount",
         CAST(COALESCE((
           SELECT SUM(p.plan_amount) FROM fund_plan p
           WHERE p.plan_start_date <= d.report_date AND p.plan_end_date >= d.report_date
             AND (CAST(:fundSubjectId AS bigint) IS NULL OR p.fund_subject_id = CAST(:fundSubjectId AS bigint))
         ), 0) AS numeric) AS "planAmount",
         CAST(COALESCE(SUM(v.debit_total), 0) AS numeric) AS "actualAmount"
  FROM fund_daily_report d
  LEFT JOIN journal_voucher v ON v.voucher_date = d.report_date AND v.status = '승인'
  WHERE d.report_date BETWEEN CAST(:fromDate AS date) AND CAST(:toDate AS date)
  GROUP BY d.fund_daily_report_id, d.report_date, d.approval_status`;

function textOf(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function idOf(value: unknown, label: string): number | null {
  const text = textOf(value);
  if (text === '') {
    return null;
  }
  if (!DIGITS.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 형식이 올바르지 않습니다.');
  }
  return Number(text);
}

@Controller('api/v1')
export class FnSfr00904Controller {
  @Get('/fund-statuses')
  async listFundStatuses(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const query = checks.queryOf(req.query);
    const statusType = textOf(query['statusType']);
    const fromDate = textOf(query['fromDate']);
    const toDate = textOf(query['toDate']);
    if (statusType === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '현황 유형을 선택하세요.');
    }
    if (!DATE_FORMAT.test(fromDate) || !DATE_FORMAT.test(toDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 기간을 YYYY-MM-DD 형식으로 입력하세요.');
    }
    const partnerAccountId = idOf(query['partnerAccountId'], '거래처 계좌');
    const fundSubjectId = idOf(query['fundSubjectId'], '자금과목');
    const pageText = textOf(query['page']);
    const sizeText = textOf(query['size']);
    if ((pageText !== '' && !DIGITS.test(pageText)) || (sizeText !== '' && !DIGITS.test(sizeText))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 정보가 올바르지 않습니다.');
    }
    const page = pageText === '' ? 0 : Number(pageText);
    const size = sizeText === '' ? DEFAULT_SIZE : Math.min(Math.max(Number(sizeText), 1), MAX_SIZE);
    let baseSql = '';
    if (statusType === TYPE_PLAN_VS_ACTUAL) {
      baseSql = PLAN_VS_ACTUAL_SQL;
    } else if (statusType === TYPE_PROFIT) {
      baseSql = PROFIT_SQL;
    } else if (statusType === TYPE_DAILY) {
      baseSql = DAILY_SQL;
    } else {
      // TODO(질문): 나머지 현황 유형은 원천 테이블이 입력에 없어 구현하지 못했다.
      throw new ApiError(400, 'VALIDATION_FAILED', '지원하지 않는 현황 유형입니다.');
    }
    return transaction(async (db) => {
      const range = await db.query(
        `SELECT CAST(:fromDate AS date) > CAST(:toDate AS date) AS "invalid"`,
        { fromDate, toDate },
      );
      if (range[0] && range[0]['invalid'] === true) {
        throw new ApiError(422, 'INVALID_DATE_RANGE', '조회 시작일이 종료일보다 늦을 수 없습니다.');
      }
      if (partnerAccountId !== null) {
        const found = await db.query(
          `SELECT partner_account_id AS "partnerAccountId" FROM partner_account WHERE partner_account_id = CAST(:partnerAccountId AS bigint)`,
          { partnerAccountId },
        );
        if (found.length === 0) {
          throw new ApiError(404, 'NOT_FOUND', '거래처 계좌를 찾을 수 없습니다.');
        }
      }
      const params = { fromDate, toDate, fundSubjectId };
      const counted = await db.query(`SELECT COUNT(*) AS "total" FROM (` + baseSql + `) t`, params);
      const total = Number(counted[0]['total']);
      const rows = await db.query(
        baseSql + ` ORDER BY 1, 2 LIMIT :size OFFSET :offset`,
        { ...params, size, offset: page * size },
      );
      const items = rows.map((row: Record<string, unknown>) => {
        const planAmount = Number(row['planAmount']);
        const actualAmount = Number(row['actualAmount']);
        return { ...row, planAmount, actualAmount, differenceAmount: actualAmount - planAmount };
      });
      // 가정: 거래처 계좌 조건은 확인만 하고 실적 필터에는 쓰지 않는다 (실적 원천에 계좌 연결 없음).
      return { items, page, size, total };
    });
  }
}

