import { useState } from 'react';
import { Band, DataTable, DateInput, DateText, Field, Filters, LookupSelect, Num, Pager, Select, Tiles, ErrorText, Badge, call, useData } from '../kit';
import type { Column, Page, PageProps, Row } from '../kit';

const TYPE_OPTIONS: [string, string][] = [
  ['자금계획 대비 실적', '자금계획 대비 실적'],
  ['자금손익현황', '자금손익현황'],
  ['일일자금 및 분개현황', '일일자금 및 분개현황'],
];

const AMOUNT_COLUMNS: Column[] = [
  { key: 'planAmount', label: '계획 금액', render: (row) => <Num value={row.planAmount} /> },
  { key: 'actualAmount', label: '실적 금액', render: (row) => <Num value={row.actualAmount} /> },
  { key: 'differenceAmount', label: '계획 대비 실적 차이', render: (row) => <Num value={row.differenceAmount} /> },
];

function columnsOf(statusType: string): Column[] {
  if (statusType === '자금손익현황') {
    return [
      { key: 'formName', label: '자금 손익 양식명' },
      { key: 'subjectName', label: '자금과목' },
      ...AMOUNT_COLUMNS,
    ];
  }
  if (statusType === '일일자금 및 분개현황') {
    return [
      { key: 'reportDate', label: '자금일보 일자', render: (row) => <DateText value={row.reportDate} /> },
      { key: 'approvalStatus', label: '결재 상태', render: (row) => <Badge value={row.approvalStatus} /> },
      { key: 'voucherCount', label: '전표 수', render: (row) => <Num value={row.voucherCount} /> },
      ...AMOUNT_COLUMNS,
    ];
  }
  return [
    { key: 'cashDirection', label: '입출금 구분' },
    ...AMOUNT_COLUMNS,
  ];
}

export default function FnSfr00904Page({ role, notify }: PageProps) {
  const [statusType, setStatusType] = useState('');
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [partnerAccountId, setPartnerAccountId] = useState<number | string>('');
  const [fundSubjectId, setFundSubjectId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [pageNo, setPageNo] = useState(0);
  const [formError, setFormError] = useState('');

  const { data, error, loading } = useData<Page | null>(async () => {
    if (applied === null) {
      return null;
    }
    return call<Page>('GET', '/fund-statuses', role, undefined, { ...applied, page: pageNo, size: 20 });
  }, [applied, pageNo]);

  function search() {
    if (statusType === '' || fromDate === '' || toDate === '') {
      setFormError('현황 유형과 조회 기간을 입력하세요.');
      return;
    }
    if (fromDate > toDate) {
      setFormError('조회 시작일이 종료일보다 늦을 수 없습니다.');
      return;
    }
    setFormError('');
    setPageNo(0);
    setApplied({ statusType, fromDate, toDate, partnerAccountId, fundSubjectId });
  }

  function reset() {
    setStatusType('');
    setFromDate('');
    setToDate('');
    setPartnerAccountId('');
    setFundSubjectId('');
    setFormError('');
    setApplied(null);
    setPageNo(0);
  }

  const rows = data ? data.items : [];
  let planSum = 0;
  let actualSum = 0;
  rows.forEach((row) => {
    planSum += Number(row.planAmount) || 0;
    actualSum += Number(row.actualAmount) || 0;
  });

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>현황 합계</h2>
        <Tiles
          items={[
            ['계획 금액', <Num value={planSum} />],
            ['실적 금액', <Num value={actualSum} />],
            ['계획 대비 실적 차이', <Num value={actualSum - planSum} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>자금현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="현황 유형" required>
            <Select value={statusType} onChange={setStatusType} options={TYPE_OPTIONS} />
          </Field>
          <Field label="조회 시작일" required>
            <DateInput value={fromDate} onChange={setFromDate} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={toDate} onChange={setToDate} />
          </Field>
          <Field label="거래처 계좌 ID">
            <LookupSelect table="partner_account" role={role} value={partnerAccountId} onChange={setPartnerAccountId} />
          </Field>
          <Field label="자금과목">
            <LookupSelect table="fund_subject" role={role} value={fundSubjectId} onChange={setFundSubjectId} />
          </Field>
        </Filters>
        {formError !== '' && <ErrorText text={formError} />}
        {error !== '' && <ErrorText text={error} />}
        <Band total={data ? data.total : 0} />
        <DataTable
          columns={columnsOf(applied ? String(applied.statusType) : '')}
          rows={rows}
          empty={loading ? '불러오는 중입니다.' : '조회 결과가 없습니다.'}
        />
        <Pager page={pageNo} size={20} total={data ? data.total : 0} onPage={setPageNo} />
      </section>
    </div>
  );
}
